func (g *gx) linkRaise(ci *closureInfo, b *Func, stack []ast.Node, n0 int) {
	for _, o := range ci.owners[n0:] {
		o := o
		if o.How == "compare" {
			ownerLinks[o] = func() *xRaise {
				for i, r := range ci.raises {
					if r.File == o.File && r.Line > o.Line && r.Line <= o.Line+3 && r.Status != nil && *r.Status/100 == 4 {
						return &ci.raises[i]
					}
				}
				return nil
			}
		}
	}
	return
